package main

import (
	"math"
)

type Line struct {
	Price, Qty int64
	Taxable   bool
}

func Compute(lines []Line, discountBP, taxBP int64) int64 {
	total := 0.0

	for _, line := range lines {
		discountedPrice := line.Price * (1 - float64(discountBP)/10000)
		discountedAmount := float64(line.Qty) * float64(discountedPrice)
		discountedAmount = math.Round(discountedAmount*100) / 100

		if line.Taxable {
			tax := discountedAmount * float64(taxBP)/10000
			discountedAmount += tax
		}

		total += discountedAmount
	}

	return int64(total)
}
